      let child = node.children.get(ch);
      if (!child) {
        child = new TrieNode();
        node.children.set(ch, child);
        this.#nodeCount += 1;
      }
      node = child;
      node.count += 1;
    }
    if (!node.isWord) {
      node.isWord = true;
      isNew = true;
    }
    const previous = isNew ? undefined : node.value;
    node.value = value;
    return previous;
  }

