   * Walks to the node for a word, or returns null if the path doesn't exist.
   * @param {string} word Word to walk.
   * @returns {TrieNode | null} The node, or null.
   */
  #walk(word) {
    let node = this.#root;
    for (const ch of toCodePoints(word)) {
      const child = node.children.get(ch);
      if (!child) return null;
      node = child;
    }
    return node;
  }

